import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as i,af as l}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Human-in-the-Loop Patterns","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/agent/human-in-the-loop-patterns.md","filePath":"zh/tech/agent/human-in-the-loop-patterns.md","lastUpdated":1780925113000}'),n={name:"zh/tech/agent/human-in-the-loop-patterns.md"};function o(r,a,h,s,p,d){return i(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="human-in-the-loop-patterns" tabindex="-1">Human-in-the-Loop Patterns <a class="header-anchor" href="#human-in-the-loop-patterns" aria-label="Permalink to &quot;Human-in-the-Loop Patterns&quot;">​</a></h1><blockquote><p>原文: <a href="https://claude.com/blog/human-in-the-loop-agentic-ai" target="_blank" rel="noreferrer">https://claude.com/blog/human-in-the-loop-agentic-ai</a></p><p>⚠️ 注意：原链接 <code>https://claude.com/blog/human-in-the-loop-agentic-ai</code> 已失效（404）。以下内容基于网络搜索到的相关信息整理。</p></blockquote><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>Human-in-the-Loop（人在回路，HITL）是一种将人类判断融入 AI 系统流程的设计模式，构成流程的运行闭环。在 Agentic AI 系统中，HITL 扮演关键角色，用于在关键决策点确保系统行为符合预期。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="什么是-human-in-the-loop" tabindex="-1">什么是 Human-in-the-Loop <a class="header-anchor" href="#什么是-human-in-the-loop" aria-label="Permalink to &quot;什么是 Human-in-the-Loop&quot;">​</a></h3><p>人在回路（Human-in-the-Loop，HITL）是人工智能的一个分支，利用人类和机器智能来创建机器学习模型或在 AI 系统运行中引入人工参与。其核心理念是：</p><ul><li>在关键决策点或遇到不确定性时，Agent 会请求人类用户的反馈或指导</li><li>人类的干预有助于确保 Agent 的行为符合预期</li><li>解决潜在的错误或偏差</li></ul><h3 id="为什么需要-hitl" tabindex="-1">为什么需要 HITL <a class="header-anchor" href="#为什么需要-hitl" aria-label="Permalink to &quot;为什么需要 HITL&quot;">​</a></h3><p>AI Agent 系统从&quot;工具&quot;向&quot;可靠队友&quot;转型的核心挑战在于平衡：</p><ul><li><strong>能力 vs 信任</strong></li><li><strong>自治 vs 问责</strong></li></ul><p>2026 年的关键洞见：协作成功率不再仅仅取决于单一模型的能力，而更多地取决于<strong>渐进式委托 + 多智能体编排</strong>的设计。</p><h2 id="hitl-的应用场景" tabindex="-1">HITL 的应用场景 <a class="header-anchor" href="#hitl-的应用场景" aria-label="Permalink to &quot;HITL 的应用场景&quot;">​</a></h2><h3 id="_1-关键决策点" tabindex="-1">1. 关键决策点 <a class="header-anchor" href="#_1-关键决策点" aria-label="Permalink to &quot;1. 关键决策点&quot;">​</a></h3><p>在涉及高风险或不可逆决策的场景：</p><ul><li>金融交易审批</li><li>内容删除/封禁</li><li>自动化测试通过/失败判定</li></ul><h3 id="_2-不确定性处理" tabindex="-1">2. 不确定性处理 <a class="header-anchor" href="#_2-不确定性处理" aria-label="Permalink to &quot;2. 不确定性处理&quot;">​</a></h3><p>当 Agent 置信度低于阈值时：</p><ul><li>主动请求人工确认</li><li>提供多个选项让人类选择</li><li>展示推理过程供人类审查</li></ul><h3 id="_3-质量控制" tabindex="-1">3. 质量控制 <a class="header-anchor" href="#_3-质量控制" aria-label="Permalink to &quot;3. 质量控制&quot;">​</a></h3><p>在 Agent 输出到达用户前进行人工审核：</p><ul><li>客服回复审核</li><li>自动化报告审查</li><li>生成内容的后编辑</li></ul><h3 id="_4-持续学习" tabindex="-1">4. 持续学习 <a class="header-anchor" href="#_4-持续学习" aria-label="Permalink to &quot;4. 持续学习&quot;">​</a></h3><p>利用人类反馈改进 Agent 行为：</p><ul><li>标注错误案例</li><li>纠正 Agent 误解</li><li>补充 Agent 缺失的领域知识</li></ul><h2 id="hitl-实现模式" tabindex="-1">HITL 实现模式 <a class="header-anchor" href="#hitl-实现模式" aria-label="Permalink to &quot;HITL 实现模式&quot;">​</a></h2><h3 id="模式一-中断等待确认-interrupt-wait" tabindex="-1">模式一：中断等待确认（Interrupt &amp; Wait） <a class="header-anchor" href="#模式一-中断等待确认-interrupt-wait" aria-label="Permalink to &quot;模式一：中断等待确认（Interrupt &amp; Wait）&quot;">​</a></h3><p>Agent 在关键步骤暂停，等待人类确认后再继续。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent → 检测到关键点 → 中断，等待人类 → 人类确认 → 继续执行</span></span></code></pre></div><p>适用于：高风险操作、首次执行新类型任务</p><h3 id="模式二-批准后执行-approval-required" tabindex="-1">模式二：批准后执行（Approval Required） <a class="header-anchor" href="#模式二-批准后执行-approval-required" aria-label="Permalink to &quot;模式二：批准后执行（Approval Required）&quot;">​</a></h3><p>Agent 生成建议，人类审批后执行。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent 生成建议 → 展示给人类 → 人类批准/修改 → Agent 执行</span></span></code></pre></div><p>适用于：需要人类最终决策的场景</p><h3 id="模式三-平行审核-parallel-review" tabindex="-1">模式三：平行审核（Parallel Review） <a class="header-anchor" href="#模式三-平行审核-parallel-review" aria-label="Permalink to &quot;模式三：平行审核（Parallel Review）&quot;">​</a></h3><p>Agent 执行同时，人类异步审核。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent 执行 → 结果同时发给人类审核 → 发现问题则回滚/修正</span></span></code></pre></div><p>适用于：实时性要求高但也需要质量控制的场景</p><h3 id="模式四-渐进式委托-progressive-delegation" tabindex="-1">模式四：渐进式委托（Progressive Delegation） <a class="header-anchor" href="#模式四-渐进式委托-progressive-delegation" aria-label="Permalink to &quot;模式四：渐进式委托（Progressive Delegation）&quot;">​</a></h3><p>根据 Agent 表现逐步增加其自主权。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>新场景 → 全部人工确认 → 部分自主 → 完全自主</span></span></code></pre></div><p>通过学习人类反馈，Agent 逐步获得更多自主权。</p><h2 id="hitl-在-agentic-ai-中的角色" tabindex="-1">HITL 在 Agentic AI 中的角色 <a class="header-anchor" href="#hitl-在-agentic-ai-中的角色" aria-label="Permalink to &quot;HITL 在 Agentic AI 中的角色&quot;">​</a></h2><h3 id="与-agent-loop-的集成" tabindex="-1">与 Agent Loop 的集成 <a class="header-anchor" href="#与-agent-loop-的集成" aria-label="Permalink to &quot;与 Agent Loop 的集成&quot;">​</a></h3><p>OpenAI Agents SDK 和类似框架提供了内置的 HITL 机制：</p><ol><li><strong>定义中断点</strong>: 在工作流中标记需要人工参与的位置</li><li><strong>状态保存</strong>: Agent 在中断时保存完整状态</li><li><strong>恢复机制</strong>: 人工决策后 Agent 从断点恢复</li></ol><h3 id="关键设计考虑" tabindex="-1">关键设计考虑 <a class="header-anchor" href="#关键设计考虑" aria-label="Permalink to &quot;关键设计考虑&quot;">​</a></h3><table tabindex="0"><thead><tr><th>考虑</th><th>说明</th></tr></thead><tbody><tr><td><strong>何时中断</strong></td><td>高风险操作、置信度低、首次执行新任务</td></tr><tr><td><strong>中断形式</strong></td><td>同步等待、异步通知、仅记录</td></tr><tr><td><strong>恢复策略</strong></td><td>完全重启、从断点恢复、降级处理</td></tr><tr><td><strong>用户体验</strong></td><td>中断不应过于频繁，否则影响效率</td></tr></tbody></table><h2 id="hitl-的权衡" tabindex="-1">HITL 的权衡 <a class="header-anchor" href="#hitl-的权衡" aria-label="Permalink to &quot;HITL 的权衡&quot;">​</a></h2><h3 id="优势" tabindex="-1">优势 <a class="header-anchor" href="#优势" aria-label="Permalink to &quot;优势&quot;">​</a></h3><ul><li>提高系统可靠性和安全性</li><li>减少错误决策的负面影响</li><li>建立人类对 AI 系统的信任</li><li>能够处理新颖/未见过的场景</li></ul><h3 id="劣势" tabindex="-1">劣势 <a class="header-anchor" href="#劣势" aria-label="Permalink to &quot;劣势&quot;">​</a></h3><ul><li>增加延迟，降低自动化效率</li><li>需要人类持续参与，消耗人力</li><li>可能成为扩展瓶颈</li><li>需要设计良好的用户界面</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ol><li><strong>仅在必要时中断</strong>: 过度中断会降低效率并让用户厌烦</li><li><strong>提供足够的上下文</strong>: 人工决策需要充分的信息</li><li><strong>清晰的确认界面</strong>: 让人类能快速做出决定</li><li><strong>记录和反馈</strong>: 所有人工干预都应被记录用于改进</li><li><strong>渐进式信任</strong>: 从严格控制开始，随系统成熟逐步放开</li></ol><h2 id="相关资源" tabindex="-1">相关资源 <a class="header-anchor" href="#相关资源" aria-label="Permalink to &quot;相关资源&quot;">​</a></h2><ul><li><a href="https://openai.github.io/openai-agents-python/" target="_blank" rel="noreferrer">OpenAI Agents SDK - Human in the Loop</a> — 内置 HITL 支持</li><li><a href="https://github.com/bmad-code-org/BMAD-METHOD" target="_blank" rel="noreferrer">BMad Method</a> — AI 驱动的敏捷开发框架</li></ul>',57)])])}const q=t(n,[["render",o]]);export{m as __pageData,q as default};
